for (int i = 0; i < numberOfChecks; ++i) {
    // Generate a random direction or fixed directions
    // For simplicity, let's use fixed directions based on i
    double theta = i * M_PI / numberOfChecks;
    double phi = i * 2 * M_PI / numberOfChecks;

    // Create direction vector
    double dx = std::sin(theta) * std::cos(phi);
    double dy = std::sin(theta) * std::sin(phi);
    double dz = std::cos(theta);

    // Create ray from point p in this direction
    CGALPoint rayOrigin(p.x(), p.y(), p.z());
    CGALPoint rayDirection(dx, dy, dz);
    CGALRay ray(rayOrigin, rayDirection);

    // Count intersections with the mesh
    int intersections = tree.number_of_intersected_primitives(ray);

    // If odd number of intersections, point is inside
    if (intersections % 2 == 1) {
        countInside++;
    }
}

// Return true if at least half of the rays had odd intersections
return countInside > numberOfChecks / 2;

